## Why This Is Asked
This question tests candidates' familiarity with DOM manipulation, fetch, WebSocket, and Service Workers in a practical offline-first scenario.

## Key Concepts
- **Offline-first UX**: Using IndexedDB and Service Worker for data persistence and asset caching
- **Real-time updates**: WebSocket integration with in-order delivery (sequenceId) and deduplication (noteId)
- **Efficient rendering**: Debounced renders and diff-based DOM updates to minimize reflows
- **Offline queue**: Storing writes in IndexedDB when offline, then syncing with exponential backoff on reconnect

## Code Example
```javascript
function debounceRender(render, wait = 120) {
  let timeout;
  return function(...args) {
    clearTimeout(timeout);
    timeout = setTimeout(() => render.apply(this, args), wait);
  };
}

class NotesWidget {
  constructor() {
    this.notes = new Map();
    this.pendingQueue = [];
    this.sequenceId = 0;
    this.render = debounceRender(this.render.bind(this));
  }

  async init() {
    await this.loadNotes();
    this.connectWebSocket();
    this.registerServiceWorker();
    this.setupOfflineQueue();
  }

  async loadNotes() {
    const res = await fetch('/notes');
    const notes = await res.json();
    notes.forEach(note => this.notes.set(note.id, note));
    this.render();
  }

  connectWebSocket() {
    this.ws = new WebSocket('wss://api.example.com/notes');
    this.ws.onmessage = (event) => {
      const { data } = JSON.parse(event.data);
      if (data.sequenceId >= this.sequenceId) {
        this.sequenceId = data.sequenceId;
        if (!this.notes.has(data.noteId)) {
          this.notes.set(data.noteId, data);
          this.render();
        }
      }
    };
  }

  async addNote(content) {
    const note = { id: crypto.randomUUID(), content, timestamp: Date.now() };
    if (navigator.onLine) {
      await fetch('/notes', {
        method: 'POST',
        body: JSON.stringify(note),
        headers: { 'Content-Type': 'application/json' }
      });
    } else {
      await this.queueNote(note);
    }
  }

  async queueNote(note) {
    const db = await indexedDB.open('notes-queue', 1);
    const tx = db.transaction('pending', 'readwrite');
    tx.objectStore('pending').add({ ...note, retryCount: 0 });
  }

  async syncQueue() {
    const db = await indexedDB.open('notes-queue', 1);
    const tx = db.transaction('pending', 'readwrite');
    const store = tx.objectStore('pending');
    const request = store.getAll();

    request.onsuccess = async () => {
      for (const note of request.result) {
        try {
          await fetch('/notes', {
            method: 'POST',
            body: JSON.stringify(note),
            headers: { 'Content-Type': 'application/json' }
          });
          store.delete(note.id);
        } catch (e) {
          await this.exponentialBackoff(note, note.retryCount++);
        }
      }
    };
  }

  async exponentialBackoff(note, attempt) {
    const delay = Math.min(1000 * Math.pow(2, attempt), 30000);
    setTimeout(() => this.queueNote(note), delay);
  }

  render() {
    // Diff-based DOM update logic here
  }
}
```

For optimistic updates, you separate the optimistic UI state from the actual server state. Here's a useReducer implementation:

```javascript
const initialState = {
  data: null,
  status: 'idle', // 'idle' | 'pending' | 'success' | 'error'
  previousData: null,
  error: null
};

function reducer(state, action) {
  switch (action.type) {
    case 'OPTIMISTIC_UPDATE':
      return {
        ...state,
        previousData: state.data,
        data: action.payload,
        status: 'pending'
      };
    case 'SUCCESS':
      return {
        ...state,
        status: 'success',
        previousData: null
      };
    case 'ERROR':
      return {
        ...state,
        status: 'error',
        data: state.previousData, // rollback
        previousData: null,
        error: action.error
      };
    default:
      return state;
  }
}

// Usage in component:
const [state, dispatch] = useReducer(reducer, initialState);

const handleUpdate = async (newData) => {
  dispatch({ type: 'OPTIMISTIC_UPDATE', payload: newData });
  try {
    await api.update(newData);
    dispatch({ type: 'SUCCESS' });
  } catch (error) {
    dispatch({ type: 'ERROR', error });
  }
};
```

The useState approach uses useEffect for the server call:

```javascript
const [data, setData] = useState(null);
const [isPending, setIsPending] = useState(false);
const [error, setError] = useState(null);

const handleUpdate = async (newData) => {
  const previousData = data;
  setData(newData); // optimistic update
  setIsPending(true);
  try {
    await api.update(newData);
  } catch (error) {
    setData(previousData); // rollback
    setError(error);
  } finally {
    setIsPending(false);
  }
};
```

For race conditions with multiple rapid updates, use AbortController to cancel in-flight requests:

```javascript
const abortRef = useRef(null);

const handleUpdate = async (newData) => {
  // Cancel any in-flight request
  abortRef.current?.abort();

  const controller = new AbortController();
  abortRef.current = controller;

  setData(newData); // optimistic
  try {
    await api.update(newData, { signal: controller.signal });
  } catch (error) {
    if (error.name !== 'AbortError') {
      setData(previousData);
    }
  }
};
```

Alternatively, use version/sequence tracking to ignore stale responses:

```javascript
const versionRef = useRef(0);

const handleUpdate = async (newData) => {
  const currentVersion = ++versionRef.current;
  setData(newData);
  try {
    await api.update(newData);
    if (currentVersion !== versionRef.current) return; // stale response
    // process success
  } catch (error) {
    if (currentVersion !== versionRef.current) return;
    setData(previousData); // rollback
  }
};
```

Key strategies: 1) Store previous state before optimistic update, 2) Use AbortController to cancel stale requests, 3) Track request version to ignore outdated responses, 4) Consider a queue for sequential processing of dependent updates.

## Why This Is Asked
This question tests your ability to design per-tenant, real-time UI systems with correct subscription lifecycles andization.

## Key Concepts
 performance optimization through memo- useSyncExternalStore with per-tenant data streams
- memoized selectors with stable identity keys
- React.memo for row component optimization
- conditional rendering with FeatureGate wrapper
- proper cleanup on tenant switch

## Code Example
```javascript
// Store wrapper - creates per-tenant subscription
function createTenantFlagStore(tenantId) {
  let flags = {};
  const subscribers = new Set();

  return {
    getSnapshot: () => flags,
    getServerSnapshot: () => ({}),
    subscribe: (callback) => {
      subscribers.add(callback);
      return () => subscribers.delete(callback);
    },
    updateFlag: (featureName, value) => {
      flags = { ...flags, [featureName]: value };
      subscribers.forEach(cb => cb(flags));
    }
  };
}

// Memoized selector keyed by tenantId and featureName
const featureSelectorCache = new Map();
function selectFeature(tenantId, featureName, tenantStore) {
  const key = `${tenantId}:${featureName}`;
  if (!featureSelectorCache.has(key)) {
    featureSelectorCache.set(key, createSelector(tenantStore, flags => ({
      enabled: flags[featureName]?.enabled ?? false,
      loading: flags[featureName]?.loading ?? true,
      visible: flags[featureName]?.visible ?? true
    })));
  }
  return featureSelectorCache.get(key)(useSyncExternalStore(
    tenantStore.subscribe,
    tenantStore.getSnapshot,
    tenantStore.getServerSnapshot
  ));
}

// Memoized FeatureRow
const FeatureRow = React.memo(function FeatureRow({ featureName, tenantId, store }) {
  const feature = selectFeature(tenantId, featureName, store);
  return (
    <div className="feature-row">
      {feature.loading ? <Spinner /> : 
       feature.enabled ? <FeatureContent name={featureName} /> : 
       <FeatureDisabled />}
    </div>
  );
}, (prevProps, nextProps) => {
  return prevProps.tenantId === nextProps.tenantId && 
         prevProps.featureName === nextProps.featureName;
});

// FeatureGate wrapper
function FeatureGate({ tenantId, featureName, children, fallback = null }) {
  const store = useTenantStore(tenantId);
  const feature = selectFeature(tenantId, featureName, store);

  return feature.enabled ? children : fallback;
}

// Panel integration with cleanup
function FeatureDashboard({ tenantId }) {
  const [currentTenant, setCurrentTenant] = useState(tenantId);

  useEffect(() => {
    if (currentTenant !== tenantId) {
      setCurrentTenant(tenantId);
    }
  }, [tenantId]);

  return (
    <FeatureGate tenantId={tenantId} featureName="dashboard_v2">
      <FeatureRow 
        tenantId={tenantId} 
        featureName="realtime_metrics"
        store={useTenantStore(tenantId)}
      />
    </FeatureGate>
  );
}
```

## Key Takeaways
The solution demonstrates proper separation of concerns: the store handles subscription management, selectors compute derived state efficiently, and components use React.memo to avoid unnecessary re-renders. The FeatureGate provides declarative access control, and cleanup on tenant switch is handled by useEffect's cleanup function in the store subscription.
